/* =========================================================
   보험용어 사전 (REQ-CH-015) 전용 JavaScript (안전성 강화)
   ========================================================= */

const HANA_OFFLINE_GLOSSARY = {"terms":[{"id":"hana-61","initial":"ㄱ","title":"가망고객","definition":"유망고객이라고도 하며, 보험가입 가능성이 높은 고객을 뜻한다."},{"id":"hana-60","initial":"ㄱ","title":"가입자격","definition":"간병보험은 피보험자(보험대상자)가 「누워있거나」또는 「치매」로 간병이 필요한 상태(「요간병상태」 라고 한다)라고 의사의 진단을 받은 그날부터 계속해서 요간병상태에 있는 기간이 일정기일을 초과한 경우에 보험금을 지급하는 보험으로, 보험기간은 보험기간의 첫날부터 피보험자(보험대상자)가 사망하는 때까지 종신이다."},{"id":"hana-59","initial":"ㄱ","title":"가쟁기간","definition":"보험자가 계약전 알릴의무 위반사실을 안 날로부터 1개월 이내, 또는 책임개시일로부터 보험금 지금사유가 발생하지 아니하고 2년(진단계약은 1년)이내일 때 보험회사는 보험금지급사유의 발생 전, 후를 묻지 않고 그 계약을 해지할 수 있는데, 이 기간을 가쟁기간이라고 한다. 이 기간이 지나면 보험회사가 계약을 해지할 수 없게된다. 또한 자살이나 자해행위에 의한 경우에도 계약에 대한 회사의 책임개시일로부터 2년이 경과한 경우에는 보험회사에서 해당 보험금을 지급한다. 이 경우 2년이 경과한 후의 기간을 가쟁기간의 반대라 할 수 있는 불가쟁기간이라고 한다."},{"id":"hana-58","initial":"ㄱ","title":"간병보험","definition":"간병보험은 피보험자(보험대상자)가 「누워있거나」또는 「치매」로 간병이 필요한 상태(「요간병상태」 라고 한다)라고 의사의 진단을 받은 그날부터 계속해서 요간병상태에 있는 기간이 일정기일을 초과한 경우에 보험금을 지급하는 보험으로, 보험기간은 보험기간의 첫날부터 피보험자(보험대상자)가 사망하는 때까지 종신이다."},{"id":"hana-57","initial":"ㄱ","title":"개인연금","definition":"개인이 생명보험회사나 은행 등의 금융기관과 계약해서 부금을 적립하여 그 적립금과 이자를 연금의 형식으로 받는 것을 말한다. 보험회사에서 취급하는 개인연금보험과 은행에서 취급하는 개인연금신탁의 두 가지 종류가 있으며, 세법에서 정하는 일정 조건을 충족하는 경우 소득세 공제와 같은 세제혜택이 주어진다."},{"id":"hana-56","initial":"ㄱ","title":"거치연금","definition":"연금수급권 취득 후, 일정기간 경과 후 또는 일정연령 도달 후에 비로소 연금의 지급이 개시되는 연금을 말한다. 이와 대립되는 용어로 계약이 체결된 해당연도부터 바로 연금의 지급이 개시되는 연금을 즉시연금이라 한다."},{"id":"hana-55","initial":"ㄱ","title":"건강보험","definition":"건강의 손상에 따른 경제적 손실을 보상하는 보험이라고 할 수 있다. 건강관련위험에는 상해,질병 등이 있으며, 이는 발생시기뿐만 아니라 발생여부도 불확정적이다."},{"id":"hana-54","initial":"ㄱ","title":"국민연금","definition":"노령을 위주로 장해, 조기사망 등을 보장한다."},{"id":"hana-53","initial":"ㄱ","title":"고용보험","definition":"실직을 최저수준에서 보장하고 있다."},{"id":"hana-52","initial":"ㄱ","title":"공제(deductible)","definition":"보험에서 부보위험발생으로 인한 손해의 일정금액이나 일정비율을 자기인수함을 말한다."},{"id":"hana-51","initial":"ㄱ","title":"국민생명표","definition":"전 국민을 대상으로 작성된 생명표"},{"id":"hana-50","initial":"ㄱ","title":"경험생명표","definition":"보험가입자를 대상으로 작성된 생명표"},{"id":"hana-49","initial":"ㄱ","title":"개인 재무설계(personal financial planning)","definition":"개인이나 가족의 목표를 달성하기 위한 통합적 계획(plan)을 개발하고 수행하기 위하여 그들의 재무적 목표를 이용하는 과정(process)이라고 정의할 수 있다."},{"id":"hana-48","initial":"ㄱ","title":"금융재산의 상속공제","definition":"피상속인이 사망으로 인하여 상속이 개시되는 경우 상속개시일 현재 상속재산가액 중에 예금, 주식 등의 금융재산가액에서 금융채무액을 차감한 가액에 대하여 최고 2억원까지 상속공제하는 제도 이다."},{"id":"hana-47","initial":"ㄱ","title":"교육보험","definition":"자녀의 교육자금을 종합적으로 마련할 수 있도록 설계된 보험으로서 부모사망시에는 유자녀학자금을 지급하고, 자녀입원시에는 입원보장을 하며,자녀사망시에는 기납입보험료를 지급하고 계약을 소멸시키는 2인(3인,다인) 보장보험이다."},{"id":"hana-46","initial":"ㄱ","title":"기타 보장성보험","definition":"만기시 기납입보험료를 돌려주는 보험"},{"id":"hana-45","initial":"ㄱ","title":"개인보험","definition":"보험계약의 대상이 하나의 보험계약자인 경우의 보험"},{"id":"hana-44","initial":"ㄱ","title":"개인형연금(single life annuity)","definition":"가입자 한 사람의 생명이 끝날 때까지 연금을 지급하는 것으로 개인 혹은 부부가 따로 연금을 가입하는 경우에 적합한 상품이다."},{"id":"hana-43","initial":"ㄱ","title":"거치연금(deferred annuity)","definition":"거치연금은 일시불 혹은 장기간의 보험료 납입을 통하여 구입할 수 있는 상품으로 일정한 거치기간이 지난 후부터 연금지급이 개시된다."},{"id":"hana-42","initial":"ㄱ","title":"금리확정형연금","definition":"예정이율이 확정되어 있는 연금을 금리확정형연금 혹은 전통형연금이라한다."},{"id":"hana-41","initial":"ㄱ","title":"금리연동형연금","definition":"예정이율인 부리이율이 보험사업자의 운용자산수익률을 기준으로 하는 공시이율 등에 연동되는 연금을 금리연동형연금이라고 한다."},{"id":"hana-40","initial":"ㄱ","title":"권고요율","definition":"요율산정 전담기관에서 산출하는 요율의 일종으로 자유요율을 적용하는 보험종목에 대해서 표준적인 요율을 보험자에게 사용하도록 권고하는 것이다."},{"id":"hana-39","initial":"ㄱ","title":"공제조합","definition":"공무원, 공공기업체,단체, 학교 등의 직원을 대상으로 일반적인 사회보험과 같은 급부를 주기 위한 조직"},{"id":"hana-38","initial":"ㄱ","title":"계약응당일","definition":"제2차년도 이후 매년의 계약일과 동일한 월,일을 말한다."},{"id":"hana-37","initial":"ㄱ","title":"급부","definition":"피보험자(보험대상자) 또는 보험수익자(보험금을 받는자)가 보험계약의 지급사유에 해당될 경우, 보험회사로부터 보험금 등이 지급되는 것을 말한다."},{"id":"hana-36","initial":"ㄱ","title":"경계역(위험)체","definition":"생명보험의 각 피보험체의 리스크는 과거의 경험에 의한 보험통계를 가지고 이것을 수량화할 수 있다."},{"id":"hana-35","initial":"ㄱ","title":"기업생명보험","definition":"회사 등의 법인이 기업유지를 주된 목적으로 하여 회사의 임원 또는 종업원을 피보험자(보험대상자)로 해서 회사가 계약자가 되어 보험표를 부담하는 생명보험을 말한다."},{"id":"hana-34","initial":"ㄱ","title":"계약일","definition":"보험계약을 위해서 청약서를 작성한 날을 말하며,청약서 작성과 함께 1회보험료를 납입한 경우는 계약체결일이라 한다."},{"id":"hana-33","initial":"ㄱ","title":"고지의무","definition":"보험회사는 보험계약의 청약을 받을 때 피보험자(보험대상자)의 위험도를 판단하는 요소로 현재의 건강상태,과거병력(병명, 치료기간 등) 등 사실 그대로 응답할 의무를 말한다."},{"id":"hana-32","initial":"ㄱ","title":"경과보험료","definition":"보험계약에서는 계약연도와 보험회사의 회계연도가 일치하지 않은 것이 대부분이므로, 통상 회계연도 말을 기준으로 경과기간과 미경과기간으로 구분하여 배분하는 보험료이다."},{"id":"hana-31","initial":"ㄱ","title":"가입연령","definition":"생명보험계약 체결시의 피보험자(보험대상자)의 연령."},{"id":"hana-30","initial":"ㄱ","title":"가족보험","definition":"한 상품에 가입해 가족 전원을 보장하는 보험."},{"id":"hana-29","initial":"ㄱ","title":"개인생명보험","definition":"개인생명보험이란 개개인을 위험 선택의 단위로 하고, 개인이 임의, 개별적으로 가입하는 생명보험이다."},{"id":"hana-28","initial":"ㄱ","title":"고유(固有)의 하자(瑕疵)","definition":"보험 목적이 가지는 결함적 성질을 가리키는 것이다."},{"id":"hana-27","initial":"ㄱ","title":"건강진단","definition":"보험가입시 보험회사에서 정한 의사가 피보험자의 건강상태를 진단하는 것을 말한다."},{"id":"hana-26","initial":"ㄱ","title":"고지의무위반","definition":"보험계약자 또는 피보험자가 계약체결시에 고의 또는 중대한 과실로 중요한 사실을 알리지 않거나 부실하게 알린 것을 말한다."},{"id":"hana-25","initial":"ㄱ","title":"가계보험","definition":"가정의 경제생활을 위협하는 여러 가지 위험에 대처하기 위하여 개인이 자기 책임 하에 가입하는 보험."},{"id":"hana-24","initial":"ㄱ","title":"공영보험","definition":"국가에서 공공정책상의 목적을 달성하기 위하여 마련되어 있는 보험을 말한다."},{"id":"hana-23","initial":"ㄱ","title":"국민표","definition":"생명표를 작성하는 자료,즉 관찰의 대상이 되는 인구집단을 국민전체로 한 것."},{"id":"hana-22","initial":"ㄱ","title":"감액완납보험","definition":"보험기간 중 보험료 납입이 어려워졌을 경우, 그때의 해지환급금을 재원으로 당초의 보험기간과 조건 변경 없이 가입 금액만 감액하는 보험."},{"id":"hana-21","initial":"ㄱ","title":"계약자 잉여금","definition":"보험자의 자본에서 부채를 공제한 잔액을 말한다."},{"id":"hana-20","initial":"ㄱ","title":"가정복지보험","definition":"생명보험의 양로보험에 속하는 상품으로서 보험기간은 3년, 5년, 7년, 10년의 네 종류가 있다."},{"id":"hana-19","initial":"ㄱ","title":"간이생명보험","definition":"일반적으로 의사의 건강진단 없이 가입되는 소액 보험금의 생명보험을 말한다."},{"id":"hana-18","initial":"ㄱ","title":"개발이익","definition":"보험회사로 하여금 적극적인 상품개발에 나서게 하기 위하여 개발 회사에 혜택을 주는 제도."},{"id":"hana-17","initial":"ㄱ","title":"개인대부 신용보험","definition":"금융기관과 자연인간의 비사업성 자금 대부계약 불이행 시 입은 손해를 보상하는 보험."},{"id":"hana-16","initial":"ㄱ","title":"개인변액보험","definition":"납입된 보험료의 일부를 별도 특별계정으로 운용하여 성과를 보험금에 반영하는 생명보험이다."},{"id":"hana-15","initial":"ㄱ","title":"개인보장","definition":"개인이 자기의 생활을 지키기 위해서 개인의 책임하에 마련하는 보장."},{"id":"hana-14","initial":"ㄱ","title":"거절체계약","definition":"표준체계약에 비해 위험도가 너무 높아 계약이 성립될 수 없는 계약을 말한다."},{"id":"hana-13","initial":"ㄱ","title":"계약수수료","definition":"보험설계사가 보험계약을 모집했을때 지급받는 보수를 말한다."},{"id":"hana-12","initial":"ㄱ","title":"계약의 부활","definition":"효력상실된 보험계약일지라도 일정 조건 충족 후 연체 보험료와 이자를 납입하여 계약을 회복하는 것을 말한다."},{"id":"hana-11","initial":"ㄱ","title":"계약의 적부확인","definition":"보험회사가 각 계약의 위험도를 판단하여 양질계약을 확보하기 위해 조사하는 제도."},{"id":"hana-10","initial":"ㄱ","title":"계약체결의 대리권","definition":"보험계약을 체결하는데 있어서 보험회사를 대신하여 법률상의 효력을 발생시키는 권한."},{"id":"hana-9","initial":"ㄱ","title":"계약자대출","definition":"해지환급금의 일정범위 이내에서 보험계약자에게 대출하는 제도."},{"id":"hana-8","initial":"ㄱ","title":"계약전환제도","definition":"생활설계 변화에 따라 기존 보험계약을 새로운 수용에 맞춰 변경하는 제도."},{"id":"hana-7","initial":"ㄱ","title":"고령자개호보험","definition":"노망, 식물인간 등 남의 개호를 필요로 하는 노인의 비용을 보상하는 보험."},{"id":"hana-6","initial":"ㄱ","title":"고지사항","definition":"고지의무의 대상이 되는 중요 사실 또는 사항."},{"id":"hana-5","initial":"ㄱ","title":"공시기준이율","definition":"보험개발원에서 매월 공시하는 실세금리연동형 저축성보험상품의 적용 금리."},{"id":"hana-4","initial":"ㄱ","title":"공제계약","definition":"공제사업 경영주체와 공제계약자 사이에 체결되는 약정."},{"id":"hana-3","initial":"ㄱ","title":"공제부금","definition":"공제계약자가 공제자에게 지급하는 돈. 보험의 보험료에 해당."},{"id":"hana-2","initial":"ㄱ","title":"근로자 재해보상 책임보험","definition":"근로자가 업무상 부상, 질병 또는 사망 시 사용자의 재해보상 책임을 담보하는 보험."},{"id":"hana-1","initial":"ㄱ","title":"근로자 저축보험","definition":"종업원의 사망/장해 및 만기시 보장되는 단체 양로보험 상품."},{"id":"hana-65","initial":"ㄴ","title":"낙성계약성","definition":"보험자와 계약자 사이에 합의가 이루어지면 별도 요식 없이 효력이 생기는 특성."},{"id":"hana-64","initial":"ㄴ","title":"납입유예기간","definition":"보험료가 납입되지 않은 채 그 계약의 효력이 일정 기간 존속하는 기간."},{"id":"hana-63","initial":"ㄴ","title":"노인상조보험","definition":"노후의 생활보장 및 장례 관련 소요 비용을 지원하는 보험 상품."},{"id":"hana-62","initial":"ㄴ","title":"농협생명공제","definition":"농업협동조합법에 의거해서 농업협동조합이 시행하는 공제사업."},{"id":"hana-75","initial":"ㄷ","title":"단체양로보험","definition":"종업원의 사망후 보장과 퇴직금 준비수단으로 이용되는 보험."},{"id":"hana-74","initial":"ㄷ","title":"단체생명보험","definition":"하나의 계약으로 단체소속원 전원이 일괄해서 가입할 수 있는 생명보험."},{"id":"hana-73","initial":"ㄷ","title":"단체정기보험","definition":"단체소속원을 대상으로 일괄 계약하는 1년 만기 자동갱신 정기보험."},{"id":"hana-72","initial":"ㄷ","title":"도덕적 위험","definition":"고의적 또는 우발적으로 손실을 일으키거나 손실 정도를 증가시키는 주관적 성향."},{"id":"hana-71","initial":"ㄷ","title":"단생연금","definition":"한 사람 피보험자의 생존을 조건으로 지급되는 생명연금."},{"id":"hana-70","initial":"ㄷ","title":"단기납입보험","definition":"보험료의 납입이 전체 보험기간의 종료 이전에 완료되는 보험."},{"id":"hana-69","initial":"ㄷ","title":"단체저축보험","definition":"기업이 피고용자를 피험자 단체로 해서 체결하는 연금보험계약."},{"id":"hana-68","initial":"ㄷ","title":"단체취급계약","definition":"단체의 급여에서 보험료를 공제하여 일괄 납입하는 방식의 계약."},{"id":"hana-67","initial":"ㄷ","title":"대위권","definition":"보험회사가 보험금을 지급한 후, 피보험자의 목적물 권리나 제3자에 대한 청구권을 취득하는 권리."},{"id":"hana-66","initial":"ㄷ","title":"독립대리점","definition":"2개 이상의 보험회사와 대리점계약을 맺고 보험계약을 대리하는 모집 주체."},{"id":"hana-76","initial":"ㄹ","title":"라이프니쯔방식","definition":"사고 피해자의 상실이익 계산 시 중간 이자를 복리법에 의해 공제하는 방식."},{"id":"hana-95","initial":"ㅁ","title":"무배당보험","definition":"사후 발생하는 경영손익 배당이 없는 대신 초기 보험료가 상대적으로 저렴한 상품."},{"id":"hana-94","initial":"ㅁ","title":"무진단보험","definition":"의사의 진단 없이 서면에 의한 고지만으로 가입을 승낙하는 보험."},{"id":"hana-93","initial":"ㅁ","title":"물가슬라이드형연금","definition":"물가상승률에 연동하여 연금액을 매년 상향조정하는 연금."},{"id":"hana-92","initial":"ㅁ","title":"무기한 건강보험","definition":"상해 또는 질병에 의한 취업불능을 담보로 하는 5년 이상의 장기건강보험."},{"id":"hana-91","initial":"ㅁ","title":"모집보조자","definition":"보험자를 위해 모집사무를 보조하는 대리점, 의사, 모집인, 중개인 등."},{"id":"hana-90","initial":"ㅁ","title":"미경과보험료적립금","definition":"수입보험료 중 결산일 현재 남은 차기 경과 기간에 해당하는 책임준비금."},{"id":"hana-89","initial":"ㅁ","title":"미적립채무","definition":"기발생채무 중 자산으로 적립되지 못한 부분."},{"id":"hana-88","initial":"ㅁ","title":"모집비","definition":"신계약 모집을 위해 직접적으로 사용되는 영업 경비 및 수당."},{"id":"hana-87","initial":"ㅁ","title":"면책위험","definition":"법률상 또는 약관상 보험자가 보험금 지급 의무를 지지 않는 위험."},{"id":"hana-86","initial":"ㅁ","title":"만기보험금","definition":"보험계약 만기 시 피보험자가 생존해 있을 때 지급되는 보험금."},{"id":"hana-85","initial":"ㅁ","title":"만기","definition":"정해진 보험기간이 완전히 경과하여 종료되는 시점."},{"id":"hana-84","initial":"ㅁ","title":"무배당 보험","definition":"배당금 지급이 없는 구조의 보험 상품."},{"id":"hana-83","initial":"ㅁ","title":"민영보험","definition":"개인이나 사법인이 경영 주체가 되어 운영하는 보험."},{"id":"hana-82","initial":"ㅁ","title":"모집","definition":"보험계약 체결의 대리 또는 매개를 수행하는 모든 행위."},{"id":"hana-81","initial":"ㅁ","title":"미지급보험료","definition":"사고는 발생했으나 지급 사정 미결 등으로 결산 시점까지 지급되지 않은 보험금."},{"id":"hana-80","initial":"ㅁ","title":"미경과보험료 준비금","definition":"수입보험료 중 차기로 이월되는 미경과분을 적립해두는 준비금."},{"id":"hana-79","initial":"ㅁ","title":"면책금액","definition":"소액 손해에 대한 지급 제외를 위해 계약자가 자기부담으로 설정하는 금액."},{"id":"hana-78","initial":"ㅁ","title":"면책사유","definition":"보험자가 보험금 지급 의무를 면하게 되는 법률/약관상의 사유."},{"id":"hana-77","initial":"ㅁ","title":"면책약관","definition":"책임이 면제되는 위험 및 사유를 기술한 약관 조항."},{"id":"hana-137","initial":"ㅂ","title":"불확정성","definition":"결과가 확정되지 않고 최소 2개 이상의 결과 가능성이 존재하는 상태."},{"id":"hana-136","initial":"ㅂ","title":"비보험전가","definition":"계약을 통해 손해 위험을 보험 이외의 제3자에게 이전하는 것."},{"id":"hana-135","initial":"ㅂ","title":"보험료 소득공제제도","definition":"근로소득자가 납부한 보험료의 일정액을 소득에서 공제해주는 제도."},{"id":"hana-134","initial":"ㅂ","title":"보장성보험","definition":"만기환급금이 기납입보험료를 초과하지 않는 보험."},{"id":"hana-133","initial":"ㅂ","title":"보험차익","definition":"만기보험금이나 해지환급금에서 납입보험료를 차감한 순이익 금액."},{"id":"hana-132","initial":"ㅂ","title":"보험모집인","definition":"보험사업자를 위하여 보험계약 체결을 중개하도록 등록된 자."},{"id":"hana-131","initial":"ㅂ","title":"비차익","definition":"예정사업비율이 실제 사용된 사업비율보다 높아서 발생한 이익."},{"id":"hana-130","initial":"ㅂ","title":"보험계리인","definition":"보험수리에 관한 과학적 이론과 계산 업무를 담당하는 전문 인력."},{"id":"hana-129","initial":"ㅂ","title":"보험대리점","definition":"소속 보험회사를 위하여 보험거래의 대리를 수행하는 법인 또는 개인."},{"id":"hana-128","initial":"ㅂ","title":"보험금","definition":"보험사고 발생 시 보험자가 보험수익자에게 지급하는 약정 금액."},{"id":"hana-127","initial":"ㅂ","title":"보험중개인","definition":"가입자의 입장에서 독립적으로 보험계약 체결을 매개해주는 전문가."},{"id":"hana-126","initial":"ㅂ","title":"보험계약의 체결","definition":"청약과 승낙에 의해 당사자 간 합의가 성립하는 법률 행위."},{"id":"hana-125","initial":"ㅂ","title":"부금","definition":"공제사업에서 급부 비용 충당을 위해 정기적으로 납부하는 금액."},{"id":"hana-124","initial":"ㅂ","title":"배당금","definition":"효율적 운용으로 발생한 경영 이익금을 계약자에게 환원하는 금액."},{"id":"hana-123","initial":"ㅂ","title":"배액지급","definition":"재해사망 등 특정 사유 발생 시 약정 보험금의 일정 배수를 지급하는 것."},{"id":"hana-122","initial":"ㅂ","title":"변액보험","definition":"책임준비금을 유가증권 등에 투자하여 운용 성과에 따라 보험금이 변동하는 상품."},{"id":"hana-121","initial":"ㅂ","title":"부가보험료","definition":"보험사업 경영에 필요한 경비 충당을 위해 부과되는 보험료."},{"id":"hana-120","initial":"ㅂ","title":"불가쟁조항","definition":"일정 기간이 경과하면 고지의무 위반을 이유로 계약을 해지할 수 없게 한 조항."},{"id":"hana-119","initial":"ㅂ","title":"불가쟁기간","definition":"고지의무 위반에 대한 보험자의 해지권이 소멸하는 법정 경과 기간."},{"id":"hana-118","initial":"ㅂ","title":"보험자(보험사업자)","definition":"보험계약을 체결하고 보험금 지급 책임을 지는 보험회사."},{"id":"hana-117","initial":"ㅂ","title":"보험가액","definition":"손해보험에서 피보험 목적물의 객관적 평가액(법률상 최고 보상 한도)."},{"id":"hana-116","initial":"ㅂ","title":"보험급부","definition":"계약 사유 발생 시 지급되는 보험금, 급부금 또는 현물 서비스."},{"id":"hana-115","initial":"ㅂ","title":"보험회사","definition":"보험업법에 따라 허가를 받아 보험사업을 영위하는 주식회사 등."},{"id":"hana-114","initial":"ㅂ","title":"보험계약","definition":"사고 발생 시 재산적 급부를 약속하고 대가를 받는 법률적 약정."},{"id":"hana-113","initial":"ㅂ","title":"보험증권 (보험가입증서)","definition":"보험계약의 성립과 내용을 증명하기 위하여 회사가 교부하는 증서."},{"id":"hana-112","initial":"ㅂ","title":"보험금액","definition":"보험사고 발생 시 회사가 지급하기로 약정한 최대 지급 한도액."},{"id":"hana-108","initial":"ㅂ","title":"보험료납입면제","definition":"장해 등 특정 사고 발생 시 향후 보험료 납입을 면제해주는 제도."},{"id":"hana-107","initial":"ㅂ","title":"보험기간","definition":"보험회사의 보장 책임이 지속되는 유효 기간."},{"id":"hana-106","initial":"ㅂ","title":"보험약관","definition":"보험회사와 계약자 간 권리와 의무를 규정한 표준 계약서."},{"id":"hana-103","initial":"ㅂ","title":"보험료","definition":"보장을 받는 대가로 계약자가 회사에 납입하는 금액."},{"id":"hana-162","initial":"ㅅ","title":"손실(loss)","definition":"원치 않는 원인으로 발생하는 바람직하지 않은 경제적 결과."},{"id":"hana-161","initial":"ㅅ","title":"손인(peril)","definition":"손실을 직접적으로 일으키는 원인 (예: 화재, 지진)."},{"id":"hana-160","initial":"ㅅ","title":"순수위험(pure risk)","definition":"이익의 가능성 없이 손실 또는 현상유지 가능성만 존재하는 위험."},{"id":"hana-157","initial":"ㅅ","title":"생명보험","definition":"사람의 생사, 질병, 상해 위험에 대비하여 경제적 안정을 도모하는 상부상조 제도."},{"id":"hana-156","initial":"ㅅ","title":"생명표(life table)","definition":"연령별 생존자수, 사망자수, 사망률, 평균여명 등을 통계로 작성한 표."},{"id":"hana-155","initial":"ㅅ","title":"수지상등의 원칙","definition":"장래 지급 보험금 현가와 납입 보험료 현가가 일치하도록 정하는 산정 원칙."},{"id":"hana-154","initial":"ㅅ","title":"상해보험","definition":"급격하고도 우연한 외래 사고로 인한 신체 손상을 보장하는 보험."},{"id":"hana-138","initial":"ㅅ","title":"사망표","definition":"연령별 사망 및 생존 상태를 통계 수치로 나타낸 표."},{"id":"hana-200","initial":"ㅇ","title":"위험(Risk)","definition":"손실 발생 가능성 또는 불확실성."},{"id":"hana-199","initial":"ㅇ","title":"위태(hazard)","definition":"손실 발생 가능성을 유발하거나 증대시키는 상태 및 조건."},{"id":"hana-197","initial":"ㅇ","title":"위험관리(risk management)","definition":"순수위험을 과학적으로 최소화하고 관리하는 접근 체계."},{"id":"hana-191","initial":"ㅇ","title":"연금보험","definition":"생존하는 동안 매년 또는 일정 주기로 소정액을 지급받는 보험."},{"id":"hana-190","initial":"ㅇ","title":"역선택","definition":"사고 가능성이 높은 사람이 자진하여 가입을 추진하는 현상."},{"id":"hana-186","initial":"ㅇ","title":"양로보험","definition":"사망 시뿐만 아니라 만기 생존 시에도 약정 보험금을 지급하는 생사혼합보험."},{"id":"hana-183","initial":"ㅇ","title":"예정이율","definition":"장래 보험금 지급을 위해 적립되는 보험료 운용 예상 수익률."},{"id":"hana-182","initial":"ㅇ","title":"예정사망률","definition":"보험료 계산의 기초로 사용되는 과거 통계 기반의 예상 사망률."},{"id":"hana-230","initial":"ㅈ","title":"자가보험(self-insurance)","definition":"기업이나 개인이 스스로 손실 충당금을 적립해 위험을 인수하는 형태."},{"id":"hana-229","initial":"ㅈ","title":"재무설계","definition":"가정 및 개인의 장래 목표 달성을 위해 체계적으로 자금을 준비하는 과정."},{"id":"hana-222","initial":"ㅈ","title":"즉시연금","definition":"일시납 후 계약 체결 직후부터 즉시 연금을 지급받는 형태."},{"id":"hana-216","initial":"ㅈ","title":"재보험","definition":"인수한 위험을 분산시키기 위해 회사가 다른 보험회사에 다시 가입하는 보험."},{"id":"hana-204","initial":"ㅈ","title":"정기보험","definition":"일정 기간 내에 사망했을 때만 보험금을 지급하는 순수 보장성 사망보험."},{"id":"hana-203","initial":"ㅈ","title":"종신연금","definition":"수혜자가 사망할 때까지 평생 지속적으로 연금을 받는 방식."},{"id":"hana-202","initial":"ㅈ","title":"종신보험","definition":"사망 시점에 관계없이 사망 시 무조건 보험금을 지급하는 사망 보장 보험."},{"id":"hana-240","initial":"ㅊ","title":"청약철회제도","definition":"계약 체결 후 일정 기간 내에 자유롭게 계약 청약을 철회할 수 있는 가입자 보호 제도."},{"id":"hana-238","initial":"ㅊ","title":"청약","definition":"보험계약을 목적으로 가입 희망자가 의사표시(청약서 작성)를 하는 행위."},{"id":"hana-231","initial":"ㅊ","title":"책임준비금","definition":"장래의 보험금, 환급금 지급을 충당하기 위해 법적으로 적립해두는 유휴 자금."},{"id":"hana-250","initial":"ㅌ","title":"특약(riding)","definition":"주계약에 추가하여 보장 범위를 확장하거나 보완하는 특별 약관."},{"id":"hana-264","initial":"ㅍ","title":"표준체(standard)보험","definition":"정상적인 건강 상태와 표준 위험도를 가진 대상을 위한 보험."},{"id":"hana-263","initial":"ㅍ","title":"표준미달체(substandard)보험","definition":"건강 상태나 직업 위험이 표준체보다 커서 특별 조건으로 가입시키는 대상."},{"id":"hana-262","initial":"ㅍ","title":"평준보험료(level premium)","definition":"전 기간 동일한 금액으로 평준화하여 납부하도록 설계된 정액 보험료."},{"id":"hana-256","initial":"ㅍ","title":"피보험자 (보험대상자)","definition":"보험 사고 발생의 대상이 되는 사람."},{"id":"hana-275","initial":"ㅎ","title":"확정연금(annuity certain)","definition":"생사 여부와 상관없이 정해진 기간 동안 무조건 연금을 지급하는 방식."},{"id":"hana-271","initial":"ㅎ","title":"해지환급금","definition":"계약 해지 시 약관에 따라 계약자에게 반환되는 책임준비금 적립액."},{"id":"hana-266","initial":"ㅎ","title":"해지","definition":"성립된 계약의 효력을 장래를 향해 소멸시키는 행위."}]};

(() => {
  'use strict';

  const INITIALS = ['ㄱ', 'ㄴ', 'ㄷ', 'ㄹ', 'ㅁ', 'ㅂ', 'ㅅ', 'ㅇ', 'ㅈ', 'ㅊ', 'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'];
  const CHOSEONG = ['ㄱ', 'ㄲ', 'ㄴ', 'ㄷ', 'ㄸ', 'ㄹ', 'ㅁ', 'ㅂ', 'ㅃ', 'ㅅ', 'ㅆ', 'ㅇ', 'ㅈ', 'ㅉ', 'ㅊ', 'ㅋ', 'ㅌ', 'ㅍ', 'ㅎ'];
  const FOLDED_INITIALS = { 'ㄲ': 'ㄱ', 'ㄸ': 'ㄷ', 'ㅃ': 'ㅂ', 'ㅆ': 'ㅅ', 'ㅉ': 'ㅈ' };

  const numberFormatter = new Intl.NumberFormat('ko-KR');

  // DOM 요소를 동적으로 안전하게 획득하는 게터 구조
  const getElements = () => ({
    stepBox: document.getElementById('menu-REQ-CH-015-step2'),
    searchInput: document.getElementById('searchInput'),
    searchSubmit: document.querySelector('.search-submit'),
    clearSearch: document.querySelector('.icoBtn_del'),
    initialFilters: document.getElementById('initialFilters'),
    termList: document.getElementById('termList'),
    detailPanel: document.getElementById('detailPanel'),
    detailHeading: document.getElementById('detail-heading'),
    detailDefinition: document.getElementById('detail-definition'),
    dictionaryLayout: document.getElementById('dictionaryLayout'),
    loadingState: document.getElementById('loadingState'),
    errorState: document.getElementById('errorState'),
    retryLoad: document.getElementById('retryLoad'),
    emptyState: document.getElementById('emptyState'),
    resetFilters: document.getElementById('resetFilters'),
    liveStatus: document.getElementById('liveStatus')
  });

  const state = {
    terms: [],
    byId: new Map(),
    filtered: [],
    query: '',
    initial: 'ㄱ',
    selectedId: null,
    loading: true,
    error: false
  };

  let inputTimer = null;
  let composing = false;

  function el(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function foldInitial(value) {
    return FOLDED_INITIALS[value] || value;
  }

  function initialProjection(value) {
    let text = '';
    const positions = [];
    for (let i = 0; i < value.length; i++) {
      const char = value[i];
      const code = value.charCodeAt(i);
      if (/\s/.test(char)) continue;
      
      const initial = (code >= 0xAC00 && code <= 0xD7A3)
        ? CHOSEONG[Math.floor((code - 0xAC00) / 588)]
        : char.toLocaleLowerCase('ko-KR');
      
      text += foldInitial(initial);
      positions.push(i);
    }
    return { text, positions };
  }

  function queryTokens() {
    return state.query.toLocaleLowerCase('ko-KR').split(/\s+/).filter(Boolean);
  }

  function isInitialQuery(token) {
    return /^[ㄱ-ㅎ]+$/.test(token);
  }

  function normalizedInitialQuery(token) {
    return Array.from(token, foldInitial).join('');
  }

  function matchesTerm(term, tokens) {
    return tokens.every(token => 
      isInitialQuery(token)
        ? term.initialSearch.includes(normalizedInitialQuery(token))
        : term.searchText.includes(token)
    );
  }

  function filteredTerms(terms, query, initial) {
    const tokens = query.toLocaleLowerCase('ko-KR').split(/\s+/).filter(Boolean);
    return terms.filter(term => {
      if (query) {
        return matchesTerm(term, tokens);
      }
      return term.initial === initial;
    });
  }

  function highlightedText(value) {
    const fragment = document.createDocumentFragment();
    const spans = [];
    const lower = value.toLocaleLowerCase('ko-KR');
    let projection = null;

    for (const token of queryTokens()) {
      const initialOnly = isInitialQuery(token);
      if (initialOnly && !projection) projection = initialProjection(value);
      
      const haystack = initialOnly ? projection.text : lower;
      const needle = initialOnly ? normalizedInitialQuery(token) : token;
      let from = 0;

      while (needle && from < haystack.length) {
        const found = haystack.indexOf(needle, from);
        if (found === -1) break;
        spans.push(initialOnly
          ? [projection.positions[found], projection.positions[found + needle.length - 1] + 1]
          : [found, found + needle.length]);
        from = found + needle.length;
      }
    }

    spans.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const span of spans) {
      const previous = merged[merged.length - 1];
      if (previous && span[0] <= previous[1]) {
        previous[1] = Math.max(previous[1], span[1]);
      } else {
        merged.push(span.slice());
      }
    }

    let offset = 0;
    for (const [start, end] of merged) {
      if (start > offset) fragment.append(document.createTextNode(value.slice(offset, start)));
      fragment.append(el('mark', '', value.slice(start, end)));
      offset = end;
    }
    if (offset < value.length) fragment.append(document.createTextNode(value.slice(offset)));
    return fragment;
  }

  function updateInitialButtons() {
    const els = getElements();
    if (!els.initialFilters) return;
    const buttons = els.initialFilters.querySelectorAll('.initial-button');
    
    buttons.forEach(button => {
      const initial = button.dataset.initial;
      const count = state.terms.filter(term => term.initial === initial).length;
      
      button.setAttribute('aria-label', `${initial}, ${numberFormatter.format(count)}개 용어`);
      
      const isActive = !state.query && initial === state.initial;
      if (isActive) {
        button.setAttribute('aria-current', 'page');
      } else {
        button.removeAttribute('aria-current');
      }
    });
  }

  function renderList() {
    const els = getElements();
    if (!els.termList) return;
    const fragment = document.createDocumentFragment();

    for (const term of state.filtered) {
      const button = el('button', 'term-item');
      button.type = 'button';
      button.dataset.termId = term.id;
      button.setAttribute('aria-controls', 'detailPanel');
      button.setAttribute('aria-label', `${term.title} 설명 보기`);
      
      const selected = term.id === state.selectedId;
      if (selected) {
        button.setAttribute('aria-current', 'true');
      }
      
      button.append(highlightedText(term.title));
      fragment.append(button);
    }

    els.termList.replaceChildren(fragment);
    els.termList.setAttribute('aria-busy', String(state.loading));
  }

  function renderDetail() {
    const els = getElements();
    if (!els.detailHeading || !els.detailDefinition) return;
    const term = state.byId.get(state.selectedId);
    
    if (!term) {
      els.detailHeading.textContent = '';
      els.detailDefinition.replaceChildren();
      return;
    }

    els.detailHeading.replaceChildren(highlightedText(term.title));

    const definitionFragment = document.createDocumentFragment();
    const paragraphs = term.definition.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
    
    for (const paragraph of paragraphs) {
      const p = el('p');
      p.append(highlightedText(paragraph));
      definitionFragment.append(p);
    }

    els.detailDefinition.replaceChildren(definitionFragment);
  }

  function renderResults({ resetScroll = false } = {}) {
    const els = getElements();
    state.filtered = filteredTerms(state.terms, state.query, state.initial);

    if (!state.filtered.some(term => term.id === state.selectedId)) {
      state.selectedId = state.filtered[0]?.id || null;
    }

    updateInitialButtons();

    if (els.clearSearch && els.searchInput) {
      els.clearSearch.style.display = els.searchInput.value ? 'block' : 'none';
    }

    if (els.emptyState) {
      els.emptyState.hidden = state.loading || state.error || state.filtered.length > 0;
    }
    if (els.loadingState) {
      els.loadingState.hidden = !state.loading;
    }
    if (els.errorState) {
      els.errorState.hidden = !state.error;
    }
    if (els.dictionaryLayout) {
      els.dictionaryLayout.hidden = state.loading || state.error || !state.filtered.length;
    }

    renderList();
    renderDetail();

    if (resetScroll && els.termList) {
      els.termList.scrollTop = 0;
    }
  }

  function selectTerm(id) {
    const els = getElements();
    const term = state.byId.get(id);
    if (!term || !state.filtered.some(item => item.id === id)) return;

    state.selectedId = id;

    if (els.termList) {
      els.termList.querySelectorAll('.term-item').forEach(button => {
        const selected = button.dataset.termId === id;
        if (selected) {
          button.setAttribute('aria-current', 'true');
        } else {
          button.removeAttribute('aria-current');
        }
      });
    }

    renderDetail();
  }

  function resetFilters() {
    const els = getElements();
    clearTimeout(inputTimer);
    state.query = '';
    state.initial = 'ㄱ';
    state.selectedId = null;

    if (els.searchInput) {
      els.searchInput.value = '';
    }

    renderResults({ resetScroll: true });
  }

  function applySearch() {
    const els = getElements();
    clearTimeout(inputTimer);
    state.query = els.searchInput?.value.trim().replace(/\s+/g, ' ') || '';
    renderResults({ resetScroll: true });
  }

  function loadTerms() {
    state.loading = true;
    state.error = false;
    renderResults();

    try {
      const data = HANA_OFFLINE_GLOSSARY;
      if (!Array.isArray(data.terms) || !data.terms.length) {
        throw new Error('데이터 구조 에러');
      }

      const seen = new Set();
      state.terms = data.terms.map(term => {
        if (!term.id || seen.has(term.id) || !term.title?.trim() || !term.definition?.trim()) {
          throw new Error('항목 구조 에러');
        }
        seen.add(term.id);

        const initial = foldInitial(term.initial || initialProjection(term.title).text[0]);
        const searchText = `${term.title}\n${term.definition}`.toLocaleLowerCase('ko-KR');

        return {
          id: term.id,
          title: term.title.trim(),
          definition: term.definition.trim(),
          initial: INITIALS.includes(initial) ? initial : 'ㄱ',
          searchText: searchText,
          initialSearch: initialProjection(searchText).text
        };
      });

      state.byId = new Map(state.terms.map(term => [term.id, term]));
      state.loading = false;

      renderResults();
    } catch (err) {
      state.loading = false;
      state.error = true;
      state.terms = [];
      state.byId.clear();
      renderResults();
    }
  }

  // document 글로벌 수준의 이벤트 위임 방식 (DOM 로드 타이밍 문제 해결)
  function bindGlobalEvents() {
    document.addEventListener('click', event => {
      // 1. 초성 선택 버튼 클릭
      const initialBtn = event.target.closest('.initial-button');
      if (initialBtn) {
        const targetInitial = initialBtn.dataset.initial;
        if (targetInitial) {
          state.query = '';
          const els = getElements();
          if (els.searchInput) els.searchInput.value = '';
          state.initial = targetInitial;
          renderResults({ resetScroll: true });
        }
        return;
      }

      // 2. 검색 돋보기 버튼 클릭
      if (event.target.closest('.search-submit')) {
        if (!composing) applySearch();
        return;
      }

      // 3. 검색어 삭제 버튼 클릭
      if (event.target.closest('.icoBtn_del')) {
        const els = getElements();
        if (els.searchInput) {
          els.searchInput.value = '';
          els.searchInput.focus();
        }
        applySearch();
        return;
      }

      // 4. 용어 항목 클릭
      const termItem = event.target.closest('.term-item');
      if (termItem && termItem.dataset.termId) {
        selectTerm(termItem.dataset.termId);
        return;
      }

      // 5. 초기화 / 다시 불러오기 버튼
      if (event.target.closest('#resetFilters')) {
        resetFilters();
        return;
      }
      if (event.target.closest('#retryLoad')) {
        loadTerms();
        return;
      }
    });

    // 검색어 입력창 이벤트 처리
    document.addEventListener('input', event => {
      if (event.target.id === 'searchInput') {
        const els = getElements();
        if (els.clearSearch) {
          els.clearSearch.style.display = event.target.value ? 'block' : 'none';
        }
        clearTimeout(inputTimer);
        if (composing || event.isComposing) return;
        inputTimer = setTimeout(applySearch, 150);
      }
    });

    document.addEventListener('compositionstart', event => {
      if (event.target.id === 'searchInput') {
        composing = true;
        clearTimeout(inputTimer);
      }
    });

    document.addEventListener('compositionend', event => {
      if (event.target.id === 'searchInput') {
        composing = false;
        applySearch();
      }
    });

    document.addEventListener('keydown', event => {
      if (event.target.id === 'searchInput') {
        if (event.key === 'Enter') {
          event.preventDefault();
          if (!composing) applySearch();
        } else if (event.key === 'Escape' && event.target.value) {
          event.preventDefault();
          event.target.value = '';
          applySearch();
        }
      }
    });
  }

  function init() {
    bindGlobalEvents();
    loadTerms();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();